<?php
declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use PHPUnit\Framework\TestCase;
final class CustomerPolicyPresenterTest extends TestCase {
 private function probe(string$case):array{$path=dirname(__DIR__,2).'/Support/CustomerPolicy/customer-policy-presentation-probe.php';exec(escapeshellarg(PHP_BINARY).' '.escapeshellarg($path).' '.escapeshellarg($case),$lines,$status);self::assertSame(0,$status,implode("\n",$lines));return json_decode(implode("\n",$lines),true,16,JSON_THROW_ON_ERROR);}
 public function test_classic_controls_are_native_escaped_fields_without_nested_forms():void{$r=$this->probe('cart-controls');self::assertStringContainsString('name="cetech_de_policy_tickets[native-key]"',$r['html']);self::assertStringContainsString('name="cetech_de_policy_nonce"',$r['html']);self::assertStringContainsString('name="cetech_de_policy_review" value="native-key"',$r['html']);self::assertStringNotContainsString('<form',$r['html']);self::assertSame(['cetech_de_customer_policy_review'],$r['nonces']);}
 public function test_checkout_controls_use_valid_table_rows():void{$r=$this->probe('checkout-controls');self::assertStringStartsWith('<tr',$r['html']);self::assertStringContainsString('<td colspan="2">',$r['html']);self::assertStringEndsWith('</td></tr>',$r['html']);}
 public function test_item_data_contains_escaped_wording_but_no_sanitized_controls():void{$r=$this->probe('item-data');self::assertCount(1,$r['rows']);$html=$r['rows'][0]['display'];self::assertStringContainsString('&lt;script&gt;literal&lt;/script&gt;',$html);self::assertStringNotContainsString('<input',$html);self::assertStringNotContainsString('<button',$html);self::assertStringNotContainsString('opaque-original-ticket',$html);}
 public function test_foreign_line_never_receives_other_line_wording_or_review_ticket():void{$r=$this->probe('foreign-line');self::assertSame('',$r['html']);self::assertSame([],$r['rows']);self::assertNotContains('cart',$r['calls']);}
 public function test_default_off_does_not_read_wc_session_or_register_assets():void{$r=$this->probe('off');self::assertSame('',$r['html']);self::assertSame(0,$r['wc_calls']);self::assertSame([],$r['assets']);self::assertSame([],$r['nonces']);self::assertNotContains('cart',$r['calls']);}
 public function test_saved_order_and_customer_html_plain_email_ignore_new_flag_and_current_products():void{foreach(['saved-order','saved-email-html','saved-email-plain']as$case){$r=$this->probe($case);self::assertContains('saved',$r['calls']);self::assertNotContains('enabled',$r['calls']);self::assertSame(0,$r['wc_calls']);self::assertStringContainsString('Returns',$r['html']);self::assertStringContainsString('Widget',$r['html']);self::assertStringNotContainsString('opaque-original-ticket',$r['html']);self::assertStringNotContainsString('<input',$r['html']);if('saved-email-plain'===$case){self::assertStringContainsString('<script>literal</script>',$r['html']);}else{self::assertStringContainsString('&lt;script&gt;literal&lt;/script&gt;',$r['html']);}}}
 public function test_denied_default_and_admin_email_do_not_project_saved_data():void{foreach(['saved-denied','saved-default-deny','saved-admin-email']as$case){$r=$this->probe($case);self::assertSame('',$r['html']);self::assertNotContains('saved',$r['calls']);}}
 public function test_saved_surfaces_mount_at_separate_hooks_with_native_arity():void{$r=$this->probe('hooks');self::assertContains(['woocommerce_order_details_after_order_table',20,1],$r['hooks']);self::assertContains(['woocommerce_email_after_order_table',20,4],$r['hooks']);self::assertContains(['woocommerce_review_order_after_cart_contents',20,1],$r['hooks']);}
}
